import type { readOnlyOptionType } from '../Column'
import type { TableName } from '../Table'

/**
 * Dictionary override configuration for modifying inherited column properties
 */
export type OverrideColumnType = {
    /** Specifies the table where this column is originally defined. If not specified, defaults to the table in 'extends'. */
    baseTable?: TableName
    /** Override the default value for this field. */
    default?: string
    /** Override the calculation script for calculated fields. */
    calculation?: string
    /** Override the reference qualifier for reference fields. */
    referenceQualifier?: string
    /** Override the read-only option for this field. */
    readOnlyOption?: readOnlyOptionType
    /** Override the dependent field setting. */
    dependent?: string
    /** Override whether the field is mandatory. */
    mandatory?: boolean
    /** Pairs of any supported dictionary attributes (sys_schema_attribute). */
    attributes?: Record<string, string | number | boolean>
    /** Whether the field should be displayed in the UI. */
    display?: boolean
}

/**
 * Define a dictionary override for an inherited column.
 *
 * Use to modify properties of a column inherited from a parent table
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all `OverrideColumnType` properties
 *
 * @example
 * ```typescript
 * // Make priority mandatory in incident table
 * export const incident = Table({
 *     name: 'incident',
 *     extends: 'task',
 *     schema: {
 *         priority: OverrideColumn({
 *             baseTable: 'task',
 *             mandatory: true,
 *         }),
 *     },
 * })
 * ```
 * @group Table/Columns
 */
export function OverrideColumn(config: OverrideColumnType): OverrideColumnType {
    return config
}
